mapper.select:
select menu_url , sum(case stsfdg when 4 then 1 else 0 end) as stsfdg4 , sum(case stsfdg when 3 then 1 else 0 end) as stsfdg3 , sum(case stsfdg when 2 then 1 else 0 end) as stsfdg2 , sum(case stsfdg when 1 then 1 else 0 end) as stsfdg1 , count(*) as sumCount from g_stsfdg where 1=1
and menu_url = #{menuUrl}
and year(frst_regist_pnttm) = #{searchYear}
and DATE_FORMAT(frst_regist_pnttm, '%Y%m%d') between #{startCreateDate} and #{endCreateDate}
group by menu_url

SELECT COUNT(*) as cnt from ( select DATE_FORMAT(frst_regist_pnttm, '%Y-%m-%d')as frstRegistPnttm , sum(case stsfdg when 4 then 1 else 0 end) as stsfdg4 , sum(case stsfdg when 3 then 1 else 0 end) as stsfdg3 , sum(case stsfdg when 2 then 1 else 0 end) as stsfdg2 , sum(case stsfdg when 1 then 1 else 0 end) as stsfdg1 , count(*) as sumCount from g_stsfdg where 1=1
and menu_url = #{menuUrl}
and DATE_FORMAT(frst_regist_pnttm, '%Y%m%d') between #{startCreateDate} and #{endCreateDate}
group by date(frst_regist_pnttm) order by frst_regist_pnttm desc ) a

select DATE_FORMAT(frst_regist_pnttm, '%Y-%m-%d') as frstRegistPnttm , sum(case stsfdg when 4 then 1 else 0 end) as stsfdg4 , sum(case stsfdg when 3 then 1 else 0 end) as stsfdg3 , sum(case stsfdg when 2 then 1 else 0 end) as stsfdg2 , sum(case stsfdg when 1 then 1 else 0 end) as stsfdg1 , count(*) as sumCount from g_stsfdg where 1=1
and menu_url = #{menuUrl}
and DATE_FORMAT(frst_regist_pnttm, '%Y%m%d') between #{startCreateDate} and #{endCreateDate}
group by date(frst_regist_pnttm) order by frst_regist_pnttm desc
